<?php
declare(strict_types=1);
require_once __DIR__.'/bootstrap/app.php';
$user=pf_require_advertiser($pdo);$id=filter_input(INPUT_GET,'id',FILTER_VALIDATE_INT);$error='';$notice=($_GET['reserved']??'')==='1'?'Your campaign budget is reserved and waiting for administrator review.':'';
if($_SERVER['REQUEST_METHOD']==='POST'){pf_verify_csrf();$id=filter_input(INPUT_POST,'campaign_id',FILTER_VALIDATE_INT);if(!$id)$error='Invalid campaign.';else{$pdo->beginTransaction();try{
 $q=$pdo->prepare("SELECT c.status,c.currency,s.requested_budget FROM pf_campaigns c JOIN pf_site_campaigns s ON s.campaign_id=c.id WHERE c.id=? AND c.advertiser_id=? AND c.campaign_type='SITE_DISPLAY' FOR UPDATE");$q->execute([$id,(int)$user['id']]);$c=$q->fetch();if(!$c||$c['status']!=='DRAFT')throw new RuntimeException('Only your draft campaigns can be funded.');
 $amount=round((float)$c['requested_budget'],2);if($amount<=0)throw new RuntimeException('The campaign budget is invalid.');$pdo->prepare("INSERT IGNORE INTO pf_wallets(user_id,wallet_type,currency) VALUES (?,'ADVERTISER',?)")->execute([(int)$user['id'],$c['currency']]);
 $w=$pdo->prepare("SELECT id FROM pf_wallets WHERE user_id=? AND wallet_type='ADVERTISER' AND currency=? FOR UPDATE");$w->execute([(int)$user['id'],$c['currency']]);$wid=(int)$w->fetchColumn();$b=$pdo->prepare('SELECT COALESCE(SUM(amount),0) FROM pf_wallet_ledger WHERE wallet_id=?');$b->execute([$wid]);if((float)$b->fetchColumn()+0.00001<$amount)throw new RuntimeException('Your advertiser wallet does not have enough available funds. Add funds before submitting this campaign.');
 $l=$pdo->prepare("INSERT INTO pf_wallet_ledger(wallet_id,user_id,entry_type,amount,currency,reference_type,reference_id,idempotency_key,description) VALUES (?,?,'CAMPAIGN_RESERVE',?,?,'SITE_CAMPAIGN',?,?,?)");$l->execute([$wid,(int)$user['id'],-$amount,$c['currency'],$id,'site-campaign-reserve-'.$id,'Reserved main-site advertising campaign budget']);$lid=(int)$pdo->lastInsertId();
 $pdo->prepare("INSERT INTO pf_site_campaign_reservations(campaign_id,advertiser_id,amount,currency,status,ledger_entry_id) VALUES (?,?,?,?,'RESERVED',?)")->execute([$id,(int)$user['id'],$amount,$c['currency'],$lid]);$u=$pdo->prepare("UPDATE pf_campaigns SET reserved_budget=?,status='PENDING_REVIEW' WHERE id=? AND status='DRAFT'");$u->execute([$amount,$id]);if($u->rowCount()!==1)throw new RuntimeException('Campaign status changed. Refresh and try again.');$pdo->commit();header('Location: fund-site-campaign.php?id='.$id.'&reserved=1',true,303);exit;
 }catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$error=$e instanceof RuntimeException?$e->getMessage():'Could not reserve the campaign budget.';}}}
if(!$id){http_response_code(400);exit('Campaign ID is required.');}$q=$pdo->prepare("SELECT c.id,c.title,c.status,c.currency,s.placement_key,s.requested_budget,s.starts_at,s.ends_at FROM pf_campaigns c JOIN pf_site_campaigns s ON s.campaign_id=c.id WHERE c.id=? AND c.advertiser_id=? AND c.campaign_type='SITE_DISPLAY'");$q->execute([$id,(int)$user['id']]);$c=$q->fetch();if(!$c){http_response_code(404);exit('Campaign not found.');}
?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Reserve campaign budget | PoketFlow</title><link rel="stylesheet" href="assets/marketplace.css"></head><body><header class="topbar"><a class="brand" href="index.php"><span class="brand-mark">P</span><span>Poket<span>Flow</span></span></a><nav><a href="dashboard.php">Dashboard</a><a href="campaigns.php">Campaigns</a><a href="wallet.php">Wallet</a></nav></header><main class="container"><section class="welcome"><p class="eyebrow">CAMPAIGN FUNDING</p><h1><?=pf_e($c['title'])?></h1><p class="muted">Placement: <?=pf_e($c['placement_key'])?> · Dates: <?=pf_e(substr((string)$c['starts_at'],0,10))?> to <?=pf_e(substr((string)$c['ends_at'],0,10))?> · Budget: <strong><?=pf_e($c['currency'])?> <?=number_format((float)$c['requested_budget'],2)?></strong></p></section><?php if($error):?><div class="alert"><?=pf_e($error)?></div><?php endif;?><?php if($notice):?><div class="panel"><?=pf_e($notice)?></div><?php endif;?><?php if($c['status']==='DRAFT'):?><section class="panel"><p class="muted">The full budget will be reserved from your advertiser wallet. The campaign will not be published until approved.</p><form method="post"><input type="hidden" name="_token" value="<?=pf_e(pf_csrf_token())?>"><input type="hidden" name="campaign_id" value="<?=(int)$c['id']?>"><button class="button primary" type="submit">Reserve budget & submit for review</button></form></section><?php else:?><section class="panel">Current status: <strong><?=pf_e($c['status'])?></strong></section><?php endif;?></main></body></html>
